void Check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
struct OwnedFiles {
 std::filesystem::path parent,root;std::vector<wht::DllLoader131*> loaders;
 OwnedFiles(const wchar_t* runtime){parent=std::filesystem::canonical(runtime);root=parent/(L"wht-lib-contracts-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));Check(root.is_absolute()&&root.parent_path()==parent&&std::filesystem::create_directory(root),"unique owned runtime-test folder");}
 ~OwnedFiles(){for(auto* loader:loaders)for(const auto& item:loader->loaded)FreeLibrary(item.second);std::error_code ec;const auto final=std::filesystem::weakly_canonical(root,ec);if(!ec&&final.is_absolute()&&final.parent_path()==parent&&final.filename().wstring().rfind(L"wht-lib-contracts-",0)==0)std::filesystem::remove_all(final,ec);}
};
void File(const std::filesystem::path& path){std::ofstream out(path,std::ios::binary);out<<"owned test data";Check(bool(out),"fixture file");}
