 std::vector<std::string> messages;unsigned mounts=0,logs=0;std::vector<unsigned> priorities;auto mount=[&](const std::wstring& path,unsigned priority){priorities.push_back(priority);Check(path.find(L"WHT_Lib")!=path.npos,"archive from library directory");return uintptr_t(++mounts);};auto log=[&](const std::string& text){messages.push_back(text);++logs;};
 wht::WhtLibrary131 library;auto off=library.Scan(root.wstring(),false,dll,mpq,mount,log);Check(off.loaded==1&&off.mounted==2&&off.failed==1&&off.skippedFast==1&&!off.Ok()&&dll.loaded.size()==1&&mpq.loaded.size()==2,"real matching DLL loads, invalid PE refused, archives mount, fast DLL skipped while off");Check(priorities==std::vector<unsigned>({30,31}),"library archive priority above manual mounts");
 Check(!dll.loaded.count(wht::DllIdentity131((lib/L"nested"/L"Hidden.dll").wstring())),"nonrecursive scan");Check(std::filesystem::remove(lib/L"Bad.dll"),"remove owned invalid fixture");
