 library.scanning=true;Check(!library.Command(root.wstring(),L"on",config,dll,mpq,mount,save,reload,log,report)&&writes==2,"reentrant command cannot save or load");library.scanning=false;
 wht::WhtLibrary131 phased;const auto beforeMounts=mounts;phased.StartDlls(root.wstring(),true,phasedDll,phasedMpq,log);Check(phasedDll.loaded.size()==3&&phasedMpq.loaded.empty()&&mounts==beforeMounts,"DLLs load at menu startup without invoking archive native");const auto beforeLogs=logs;phased.StartDlls(root.wstring(),true,phasedDll,phasedMpq,log);Check(logs==beforeLogs,"DLL startup once without disk scan each UI tick");phased.Start(root.wstring(),true,phasedDll,phasedMpq,mount,log);Check(phasedMpq.loaded.size()==2&&mounts==beforeMounts+2,"archives deferred to native-ready UI");phased.Start(root.wstring(),true,phasedDll,phasedMpq,mount,log);Check(mounts==beforeMounts+2,"archive startup once");
